     1	/**
     2	 * Result envelope every job returns to the scheduler.
     3	 */
     4	import { toIsoTimestamp } from "@/types/common";
     5	import type { IsoTimestamp } from "@/types/common";
     6	
     7	export type JobResult = {
     8	  kind: string;
     9	  processed: number;
    10	  failed: number;
    11	  durationMs: number;
    12	  startedAt: IsoTimestamp;
    13	};
    14	
    15	/** The zero value a job starts from and mutates as it works. */
    16	export function emptyJobResult(
    17	  kind: string,
    18	  startedAt: IsoTimestamp,
    19	): JobResult {
    20	  return { kind, processed: 0, failed: 0, durationMs: 0, startedAt };
    21	}
    22	
    23	/**
    24	 * Convenience for a job body: stamps the start, runs the work and fills in
    25	 * `durationMs`. Kept here so every job reports the same shape.
    26	 */
    27	export async function runJob(
    28	  kind: string,
    29	  work: (result: JobResult) => Promise<void>,
    30	): Promise<JobResult> {
    31	  const startedAt = toIsoTimestamp(new Date());
    32	  const began = Date.now();
    33	  const result = emptyJobResult(kind, startedAt);
    34	
    35	  await work(result);
    36	
    37	  return { ...result, durationMs: Date.now() - began };
    38	}
